import { ZendeskLookups, createEmptyLookups, TicketFieldLookup, CustomFieldDefinitionLookup } from '../../types/lookups';
import { fetchAllPages } from './pagination';
import { zendeskRequest } from './zendeskRequest';
import { zafClient } from '../zaf/zafClient';
import { ZendeskGroupRaw, ZendeskAgentRaw, ZendeskOrganizationRaw, ZendeskTicketFieldRaw, ZendeskTicketFormRaw } from '../../types/resources';

let cachedLookups: ZendeskLookups | null = null;
let lookupPromise: Promise<ZendeskLookups> | null = null;

export async function getZendeskLookups(forceRefresh = false): Promise<ZendeskLookups> {
  if (cachedLookups && !forceRefresh) {
    return cachedLookups;
  }

  if (lookupPromise && !forceRefresh) {
    return lookupPromise;
  }

  lookupPromise = (async () => {
    const lookups = createEmptyLookups();

    // Resolve subdomain
    try {
      const ctx = await zafClient.context();
      if (ctx?.account?.subdomain) {
        lookups.subdomain = ctx.account.subdomain;
      }
    } catch (err) {
      console.warn('[Lookups] Could not retrieve subdomain from ZAF context:', err);
    }
    if (!lookups.subdomain && typeof window !== 'undefined' && window.location?.hostname) {
      const match = window.location.hostname.match(/^([a-zA-Z0-9_-]+)\.zendesk\.com$/);
      if (match) {
        lookups.subdomain = match[1];
      }
    }

    // 1. Fetch Groups
    try {
      const groups = await fetchAllPages<ZendeskGroupRaw>('/api/v2/groups.json?page[size]=100', 'groups');
      for (const group of groups) {
        lookups.groups.set(group.id, group.name);
      }
    } catch (err) {
      console.warn('[Lookups] Failed to fetch groups for cross-referencing:', err);
    }

    // 1b. Fetch Group Memberships (for accurate agent counts per group and agent group associations)
    try {
      const memberships = await fetchAllPages<{ id: number; group_id: number; user_id: number }>(
        '/api/v2/group_memberships.json?page[size]=100',
        'group_memberships'
      );
      const groupUserSets = new Map<number, Set<number>>();
      for (const m of memberships) {
        if (m.group_id && m.user_id) {
          if (!groupUserSets.has(m.group_id)) {
            groupUserSets.set(m.group_id, new Set());
          }
          groupUserSets.get(m.group_id)!.add(m.user_id);

          if (!lookups.userGroupIds.has(m.user_id)) {
            lookups.userGroupIds.set(m.user_id, []);
          }
          const userGids = lookups.userGroupIds.get(m.user_id)!;
          if (!userGids.includes(m.group_id)) {
            userGids.push(m.group_id);
          }
        }
      }
      for (const [gid, set] of groupUserSets.entries()) {
        lookups.groupAgentCounts.set(gid, set.size);
      }
    } catch (err) {
      console.warn('[Lookups] Failed to fetch group memberships, will infer from agent records if available:', err);
    }

    // 2. Fetch Agents (role=agent & role=admin)
    try {
      const agents = await fetchAllPages<ZendeskAgentRaw>('/api/v2/users.json?role[]=agent&role[]=admin&page[size]=100', 'users');
      for (const agent of agents) {
        lookups.users.set(agent.id, agent.name || agent.email);
      }

      // If group memberships were not available, infer group agent counts from agent records
      if (lookups.groupAgentCounts.size === 0) {
        const groupUserSets = new Map<number, Set<number>>();
        for (const agent of agents) {
          const gids: number[] = [];
          if (Array.isArray(agent.group_ids)) {
            gids.push(...agent.group_ids);
          }
          if (agent.default_group_id && !gids.includes(agent.default_group_id)) {
            gids.push(agent.default_group_id);
          }
          for (const gid of gids) {
            if (!groupUserSets.has(gid)) {
              groupUserSets.set(gid, new Set());
            }
            groupUserSets.get(gid)!.add(agent.id);

            if (!lookups.userGroupIds.has(agent.id)) {
              lookups.userGroupIds.set(agent.id, []);
            }
            const userGids = lookups.userGroupIds.get(agent.id)!;
            if (!userGids.includes(gid)) {
              userGids.push(gid);
            }
          }
        }
        for (const [gid, set] of groupUserSets.entries()) {
          lookups.groupAgentCounts.set(gid, set.size);
        }
      }
    } catch (err) {
      console.warn('[Lookups] Failed to fetch agents for cross-referencing:', err);
    }

    // 3. Fetch Organizations
    try {
      const orgs = await fetchAllPages<ZendeskOrganizationRaw>('/api/v2/organizations.json?page[size]=100', 'organizations');
      for (const org of orgs) {
        lookups.organizations.set(org.id, org.name);
      }
    } catch (err) {
      console.warn('[Lookups] Failed to fetch organizations for cross-referencing:', err);
    }

    // 4. Fetch Ticket Fields
    try {
      const fields = await fetchAllPages<ZendeskTicketFieldRaw>('/api/v2/ticket_fields.json?page[size]=100', 'ticket_fields');
      for (const field of fields) {
        const optionMap = new Map<string, string>();
        if (field.custom_field_options) {
          for (const opt of field.custom_field_options) {
            optionMap.set(opt.value, opt.name);
          }
        }
        const lookupItem: TicketFieldLookup = {
          id: field.id,
          title: field.title,
          type: field.type,
          options: optionMap,
        };
        lookups.ticketFields.set(field.id, lookupItem);
      }
    } catch (err) {
      console.warn('[Lookups] Failed to fetch ticket fields for cross-referencing:', err);
    }

    // 5. Fetch Forms
    try {
      const forms = await fetchAllPages<ZendeskTicketFormRaw>('/api/v2/ticket_forms.json?page[size]=100', 'ticket_forms');
      for (const form of forms) {
        lookups.forms.set(form.id, form.name || form.display_name || `Form ${form.id}`);
      }
    } catch (err) {
      console.warn('[Lookups] Failed to fetch forms for cross-referencing:', err);
    }

    // 6. Fetch Brands
    try {
      const brands = await fetchAllPages<any>('/api/v2/brands.json?page[size]=100', 'brands');
      for (const brand of brands) {
        lookups.brands.set(brand.id, brand.name);
      }
    } catch (err) {
      console.warn('[Lookups] Failed to fetch brands for cross-referencing:', err);
    }

    // 7. Fetch Custom Roles (Enterprise accounts)
    try {
      const customRolesRes = await fetchAllPages<any>('/api/v2/custom_roles.json', 'custom_roles');
      for (const role of customRolesRes) {
        if (role && role.id && role.name) {
          lookups.customRoles.set(role.id, role.name);
          lookups.customRoles.set(Number(role.id), role.name);
          lookups.customRoles.set(String(role.id), role.name);
        }
      }
    } catch (err) {
      try {
        const directRes = await zendeskRequest<any>({ url: '/api/v2/custom_roles.json', type: 'GET' });
        const list = directRes?.custom_roles || [];
        for (const role of list) {
          if (role && role.id && role.name) {
            lookups.customRoles.set(role.id, role.name);
            lookups.customRoles.set(Number(role.id), role.name);
            lookups.customRoles.set(String(role.id), role.name);
          }
        }
      } catch (innerErr) {
        console.warn('[Lookups] Custom roles not available or restricted on this plan:', innerErr);
      }
    }

    // 8. Fetch Business Hours Schedules
    try {
      const schedulesRes = await fetchAllPages<any>('/api/v2/business_hours/schedules.json', 'schedules');
      for (const sched of schedulesRes) {
        if (sched && sched.id && sched.name) {
          lookups.schedules.set(sched.id, sched.name);
          lookups.schedules.set(Number(sched.id), sched.name);
          lookups.schedules.set(String(sched.id), sched.name);
        }
      }
    } catch (err) {
      try {
        const directSched = await zendeskRequest<any>({ url: '/api/v2/business_hours/schedules.json', type: 'GET' });
        const list = directSched?.schedules || [];
        for (const sched of list) {
          if (sched && sched.id && sched.name) {
            lookups.schedules.set(sched.id, sched.name);
            lookups.schedules.set(Number(sched.id), sched.name);
            lookups.schedules.set(String(sched.id), sched.name);
          }
        }
      } catch (innerErr) {
        console.warn('[Lookups] Failed to fetch schedules for cross-referencing:', innerErr);
      }
    }

    // 9. Fetch Trigger Categories
    try {
      const categories = await fetchAllPages<any>('/api/v2/trigger_categories.json?page[size]=100', 'trigger_categories');
      for (const cat of categories) {
        if (cat && cat.id) {
          const catInfo = {
            name: cat.name || '',
            position: Number(cat.position ?? 0),
          };
          lookups.triggerCategories.set(cat.id, catInfo);
          lookups.triggerCategories.set(String(cat.id), catInfo);
          const numId = Number(cat.id);
          if (!isNaN(numId)) {
            lookups.triggerCategories.set(numId, catInfo);
          }
        }
      }
    } catch (err) {
      try {
        const directCat = await zendeskRequest<any>({ url: '/api/v2/trigger_categories.json', type: 'GET' });
        const list = directCat?.trigger_categories || [];
        for (const cat of list) {
          if (cat && cat.id) {
            const catInfo = {
              name: cat.name || '',
              position: Number(cat.position ?? 0),
            };
            lookups.triggerCategories.set(cat.id, catInfo);
            lookups.triggerCategories.set(String(cat.id), catInfo);
            const numId = Number(cat.id);
            if (!isNaN(numId)) {
              lookups.triggerCategories.set(numId, catInfo);
            }
          }
        }
      } catch (innerErr) {
        console.warn('[Lookups] Trigger categories not available or restricted on this plan:', innerErr);
      }
    }

    // 10. Fetch Organization Fields
    try {
      const orgFields = await fetchAllPages<any>('/api/v2/organization_fields.json?page[size]=100', 'organization_fields');
      for (const field of orgFields) {
        if (field && (field.key || field.id)) {
          const optionMap = new Map<string, string>();
          if (Array.isArray(field.custom_field_options)) {
            for (const opt of field.custom_field_options) {
              optionMap.set(opt.value, opt.name);
            }
          }
          const item: CustomFieldDefinitionLookup = {
            id: field.id,
            key: field.key || String(field.id),
            title: field.title || field.raw_title || field.key || `Field ${field.id}`,
            type: field.type || 'text',
            options: optionMap,
          };
          lookups.organizationFields.push(item);
          lookups.organizationFieldsMap.set(item.key, item);
          lookups.organizationFieldsMap.set(String(item.id), item);
        }
      }
    } catch (err) {
      try {
        const directOrgFields = await zendeskRequest<any>({ url: '/api/v2/organization_fields.json', type: 'GET' });
        const list = directOrgFields?.organization_fields || [];
        for (const field of list) {
          if (field && (field.key || field.id)) {
            const optionMap = new Map<string, string>();
            if (Array.isArray(field.custom_field_options)) {
              for (const opt of field.custom_field_options) {
                optionMap.set(opt.value, opt.name);
              }
            }
            const item: CustomFieldDefinitionLookup = {
              id: field.id,
              key: field.key || String(field.id),
              title: field.title || field.raw_title || field.key || `Field ${field.id}`,
              type: field.type || 'text',
              options: optionMap,
            };
            lookups.organizationFields.push(item);
            lookups.organizationFieldsMap.set(item.key, item);
            lookups.organizationFieldsMap.set(String(item.id), item);
          }
        }
      } catch (innerErr) {
        console.warn('[Lookups] Failed to fetch organization fields:', innerErr);
      }
    }

    // 11. Fetch User Fields
    try {
      const uFields = await fetchAllPages<any>('/api/v2/user_fields.json?page[size]=100', 'user_fields');
      for (const field of uFields) {
        if (field && (field.key || field.id)) {
          const optionMap = new Map<string, string>();
          if (Array.isArray(field.custom_field_options)) {
            for (const opt of field.custom_field_options) {
              optionMap.set(opt.value, opt.name);
            }
          }
          const item: CustomFieldDefinitionLookup = {
            id: field.id,
            key: field.key || String(field.id),
            title: field.title || field.raw_title || field.key || `Field ${field.id}`,
            type: field.type || 'text',
            options: optionMap,
          };
          lookups.userFields.push(item);
          lookups.userFieldsMap.set(item.key, item);
          lookups.userFieldsMap.set(String(item.id), item);
        }
      }
    } catch (err) {
      try {
        const directUFields = await zendeskRequest<any>({ url: '/api/v2/user_fields.json', type: 'GET' });
        const list = directUFields?.user_fields || [];
        for (const field of list) {
          if (field && (field.key || field.id)) {
            const optionMap = new Map<string, string>();
            if (Array.isArray(field.custom_field_options)) {
              for (const opt of field.custom_field_options) {
                optionMap.set(opt.value, opt.name);
              }
            }
            const item: CustomFieldDefinitionLookup = {
              id: field.id,
              key: field.key || String(field.id),
              title: field.title || field.raw_title || field.key || `Field ${field.id}`,
              type: field.type || 'text',
              options: optionMap,
            };
            lookups.userFields.push(item);
            lookups.userFieldsMap.set(item.key, item);
            lookups.userFieldsMap.set(String(item.id), item);
          }
        }
      } catch (innerErr) {
        console.warn('[Lookups] Failed to fetch user fields:', innerErr);
      }
    }

    cachedLookups = lookups;
    lookupPromise = null;
    return lookups;
  })();

  return lookupPromise;
}

export function invalidateLookupCache(): void {
  cachedLookups = null;
  lookupPromise = null;
}
